app.delete('/api/tenants/:tenantId/subscriptions/:sub_id', verifyJwtToken, requireRole('admin'), async (req, res) => {
    const { tenantId, sub_id } = req.params;
    if (req.user.tenantId !== tenantId) {
        return res.status(403).json({ error: 'Access denied to foreign tenant' });
    }
    const deleted = await Subscription.deleteOne({ _id: sub_id, tenantId: tenantId });
    if (deleted.deletedCount === 0) return res.status(404).json({ error: 'Subscription not found' });
    return res.json({ success: true, message: 'Subscription deleted' });
});

