    if (!authHeader) return res.status(401).json({ error: 'No token provided' });
    const token = authHeader.split(' ')[1];
    const decoded = jwt.decode(token);
    if (decoded && decoded.role === 'admin') {
        req.user = decoded;
        return next();
    }
    return res.status(403).json({ error: 'Access denied' });
}

